      "path": "src/index.ts",
      "content": "import type { Context } from '@deepseek-ai/cordis'\n// schemastery 必须留在 dependencies,**不要**改成 peerDependencies(issue #5 的建议)。\n// 本插件装在 profile 里,而内核只把 schemastery 放在 dsh/node_modules/ 下——不在\n// 插件的 Node 向上解析路径上;profile 又设了 autoInstallPeers: false。实测改成\n// peer 后插件加载即 ERR_MODULE_NOT_FOUND。它与 dsh-settings 不同:dsh-settings 是\n// 按包名在 profile 内解析的内核行,hoisted 副本会遮蔽内核那份(故 0.4.0 已彻底移除);\n// schemastery 只是被按值 import 的库,不存在遮蔽,且这里 Schema.object() 在加载时\n// 求值,属运行期值导入而非类型标注。\nimport Schema from '@deepseek-ai/schemastery'\n// 0.2.0 起设置改为宿主按插件 Config schema 自动生成表单(SettingsForms),\n// 插件不再注册命名空间;0.1.x 线的两套 API 由下方运行时探测分派,类型只在本地声明。\nimport type { GenerateOptions, Message } from '@deepseek-ai/dsh-llm'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport { buildSystemPrompt, buildUserPayload, capConversationContext, createThinkFilter, estimateTokens, parseOptimizerOutput, type ConversationTurn, type OptimizerMode, type OutputLanguage } from './prompt.js'\n\nexport const name = 'dsh-prompt-optimizer'\n// 硬依赖只有 llm。HTTP 载体服务名在发布版间漂移过(npm 0.0.1-rc.x 类型包叫\n// httpServer,0.1.0-rc.x 运行时叫 webServer),用 ctx.inject 双名等待,避免\n// 静态 inject 声明错位时把整个 Harness 组合启动拖垮。\nexport const inject = ['llm']\n\nexport interface Config {\n  /** 优化输出的语言('zh'/'en';其他值按 'zh' 处理)。 */\n  language: string\n  /** 固定模型,'provider/model' 形式;留空 = 跟随发起请求的会话当前选择。 */\n  model?: string\n  /** 回退模型('provider/model',留空 = 无);主路由在未产出任何内容就失败时自动换用。 */\n  fallbackModel?: string\n  /** 单次优化调用的最大输出 token 数。 */\n  maxTokens: number\n  /** 单次优化调用的超时时间(秒);超时后中止模型调用并通知客户端。 */\n  timeoutSeconds: number\n  /** 优化模式('full'/'fast';0.5.0 起默认 fast——仅优化稿,等待时间约减半;其他值按 'full' 处理)。 */\n  mode: string\n  /** 推理强度('lowest'/'session';其他值按 'lowest' 处理)。默认钳最低档:优化是格式化元任务,高档推理只拉长首 token 前的空等。 */\n  reasoningEffort: string\n  /** 采样温度(0-2,默认 0.2);优化是格式化任务,低温输出更稳定。 */\n  temperature: number\n  /** 输出上限跟随输入长度(默认开):长草稿时按输入 token 估算提高 maxTokens,避免截断。 */\n  autoMaxTokens: boolean\n  /** 优化时携带会话近期对话作为上下文(默认开):方向更贴合;关闭后仅看草稿本身。 */\n  includeContext: boolean\n}\n\n// 枚举字段刻意用宽松 string 而非 union:设置文档持久化在 profile 补丁/旧版\n// settings.yaml,旧版本写过的枚举值(如 mode: custom)若撞上严格 union 会让\n// schema 校验抛错,整个配置解析失败。宽松接收 + 使用处归一化更稳。\n// 全字段 .volatile():0.2.0 起宿主只把 volatile 字段投影成 Web 设置表单\n// (SettingsForms.volatileForm),且这类字段经 Volatile 引用原位更新——\n// 设置修改不重挂载插件;0.1.x 宿主忽略该标记,行为不变。\nexport const Config = Schema.object({\n  language: Schema.string().default('zh').volatile(),\n  model: Schema.string().volatile(),\n  fallbackModel: Schema.string().volatile(),\n  maxTokens: Schema.number().min(1024).max(32768).default(8192).volatile(),\n  timeoutSeconds: Schema.number().min(10).max(600).default(120).volatile(),\n  mode: Schema.string().default('fast').volatile(),\n  reasoningEffort: Schema.string().default('lowest').volatile(),\n  temperature: Schema.number().min(0).max(2).default(0.2).volatile(),\n  autoMaxTokens: Schema.boolean().default(true).volatile(),\n  includeContext: Schema.boolean().default(true).volatile(),\n})\n\n/** 0.2.0 volatile 字段的运行时形态:宿主原位更新的引用 cell(cosmokit Volatile)。 */\ninterface VolatileCell<T> {\n  get(): T\n}\n\n/** volatile cell 按结构识别取值;普通值(0.1.x / 直调 apply)原样返回。 */\nfunction unwrapCell<T>(value: T | VolatileCell<T>): T {\n  return typeof (value as VolatileCell<T>)?.get === 'function' ? (value as VolatileCell<T>).get() : (value as T)\n}\n\n/** 把 apply 收到的 config 归一为普通值快照(0.2.0 的 volatile 字段是引用 cell)。 */\nfunction readConfig(raw: Config): Config {\n  return {\n    language: unwrapCell(raw.language),\n    model: unwrapCell(raw.model),\n    fallbackModel: unwrapCell(raw.fallbackModel),\n    maxTokens: unwrapCell(raw.maxTokens),\n    timeoutSeconds: unwrapCell(raw.timeoutSeconds),\n    mode: unwrapCell(raw.mode),\n    reasoningEffort: unwrapCell(raw.reasoningEffort),\n    temperature: unwrapCell(raw.temperature),\n    autoMaxTokens: unwrapCell(raw.autoMaxTokens),\n    includeContext: unwrapCell(raw.includeContext),\n  }\n}\n\n// 0.1.2-rc.1 起 ns 直接传字符串,由 SettingsNamespaceInput 做小写-连字符校验。\nconst NS = 'prompt-optimizer' as const\nconst ROUTE_PATH = '/dsh-prompt-optimizer/optimize'\nconst TEST_ROUTE_PATH = '/dsh-prompt-optimizer/test-model'\nconst MAX_BODY_BYTES = 256 * 1024\n\n// 并发防线:优化端点每次调用都是一次真实计费的 LLM 调用。客户端用\n// status==='loading' 挡了重复点击,但端点本身不限并发——同源多标签页或本机\n// 任意进程都能刷。超限直接 429,不排队(排队只会让额度消耗更晚爆发)。\nconst MAX_CONCURRENT_OPTIMIZES = 3\n\n// SSE 心跳:推理模型首 token 前可能几十秒无字节,经反代/隧道(LAN 暴露是\n// README 声明支持的用法)空闲超时会掐连接。注释帧 `: ping` 不被现有客户端\n// 解析器消费(它只认 `data:` 行),但足以让中间层看到连接活跃。\nconst SSE_HEARTBEAT_MS = 15_000\n\n// 客户端未携带会话 id 时,优化调用标注的合成会话 id(opencode 等提供方要求\n// 会话头才能路由,见 options 组装处);探活调用的固定标注见 testHandler。\nconst ONESHOT_SESSION_ID = 'prompt-optimizer-one-shot'\n\n// R27:宽 string schema 的配套告警(枚举值在用处处静默归一化,这里至少让用户\n// 在日志里看到自己手填的值不被支持)。每个 非法字段=值 组合只提醒一次。\n// 集合挂在 apply 闭包内(实例级):与 effortCache 一致,插件热重载/多实例\n// 时各自独立,重载后该告警能重新出现一次。\nfunction warnUnknownEnum(warned: Set<string>, value: string, allowed: readonly string[], label: string): void {\n  const key = `${label}=${value}`\n  if (!allowed.includes(value) && !warned.has(key)) {\n    warned.add(key)\n    console.warn(`[${name}] 配置 ${label}=\"${value}\" 不是有效值(支持:${allowed.join('/')}),已按默认处理`)\n  }\n}\n\n/** 对三个宽松枚举字段做非法值告警;归一化仍由各使用处完成。 */\nfunction warnUnknownEnumConfig(warned: Set<string>, cfg: Config): void {\n  if (cfg.language !== 'zh' && cfg.language !== 'en') warnUnknownEnum(warned, cfg.language, ['zh', 'en'], 'language')\n  if (cfg.mode !== 'full' && cfg.mode !== 'fast') warnUnknownEnum(warned, cfg.mode, ['full', 'fast'], 'mode')\n  if (cfg.reasoningEffort !== 'lowest' && cfg.reasoningEffort !== 'session') {\n    warnUnknownEnum(warned, cfg.reasoningEffort, ['lowest', 'session'], 'reasoningEffort')\n  }\n}\n\ninterface OptimizeRequestBody {\n  text?: unknown\n  /** 发起优化的会话 id:标注到 llm 调用上(opencode 等提供方要求会话头才能路由)。 */\n  sessionId?: unknown\n  provider?: unknown\n  model?: unknown\n  reasoningEffort?: unknown\n  context?: unknown\n  previous?: unknown\n}\n\n/** 0.1.2+ settings.installSection 的回调包(仅类型面使用)。 */\ninterface SettingsHooks {\n  setSource(source: () => Config): void\n  onChange(): void\n}\n\n/** 跨版本传递给 settings API 的 schema 最小结构面(带 toJSON 的 schemastery 实例)。 */\ninterface SettingsSchemaLike {\n  toJSON(): unknown\n}\n\nfunction asOptionalString(value: unknown): string | undefined {\n  return typeof value === 'string' && value.trim() ? value.trim() : undefined\n}\n\n/**\n * 校验客户端携带的会话上下文:只接受 {role:'user'|'assistant', text} 数组,\n * 坏条目静默丢弃,最终再过一遍预算收敛(防御性——客户端已按同一口径收敛过)。\n */\nfunction parseContextInput(value: unknown): ConversationTurn[] | undefined {\n  if (!Array.isArray(value)) return undefined\n  const turns: ConversationTurn[] = []\n  for (const item of value) {\n    if (!item || typeof item !== 'object') continue\n    const { role, text } = item as Record<string, unknown>\n    if ((role === 'user' || role === 'assistant') && typeof text === 'string' && text.trim()) {\n      turns.push({ role, text: text.trim() })\n    }\n  }\n  return turns.length ? capConversationContext(turns) : undefined\n}\n\n/**\n * 写 JSON 应答。响应头已发出(SSE 阶段)或已结束时静默跳过:此时再 writeHead\n * 会抛 ERR_HTTP_HEADERS_SENT,而它本就是从 catch 里调用的——异常会逃出路由,\n * 变成未处理的 promise rejection。\n */\nfunction writeJson(res: import('node:http').ServerResponse, status: number, body: unknown): void {\n  if (res.headersSent || res.writableEnded) return\n  const payload = JSON.stringify(body)\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'content-length': Buffer.byteLength(payload),\n  })\n  res.end(payload)\n}\n\n/**\n * 浏览器来源围栏(本机服务的 CSRF / DNS rebinding 防线):\n * - 浏览器发出的 POST 必带 Origin 头:其 authority 必须与 Host 头一致,\n *   否则拒绝——恶意网页的跨站 text/plain POST(免预检)在此被挡下;\n * - Host 头必须是回环地址,或与本次连接的实际本地地址:端口一致——\n *   DNS rebinding 会伪造 Host=攻击域名,在此被挡下;\n * - 无 Origin 的请求(CLI / 服务端调用)放行:本插件的主要调用方是\n *   同源页面与命令行,前者 Origin 恒匹配,后者本就不带该头。\n * LAN 暴露(README 已声明)不受影响:直连 IP 访问时 Host=本机地址。\n */\nfunction assertTrustedOrigin(req: IncomingMessage, res: ServerResponse): boolean {\n  const origin = req.headers.origin\n  if (!origin) return true\n  const host = req.headers.host\n  let originHost = ''\n  try {\n    originHost = new URL(origin).host\n  } catch {\n    originHost = ''\n  }\n  if (!host || originHost !== host) {\n    writeJson(res, 403, { ok: false, error: '已拒绝跨站请求(Origin 与 Host 不符)' })\n    return false\n  }\n  const hostName = host.replace(/:\\d+$/, '')\n  const hostPort = /:(\\d+)$/.exec(host)?.[1] ?? '80'\n  const loopback = hostName === 'localhost' || hostName === '127.0.0.1' || hostName === '[::1]' || hostName === '::1'\n  if (!loopback) {\n    // Host 不是回环时,必须恰好等于本次连接的本地地址:端口(直连 IP 的 LAN 访问);\n    // 拿不到 socket 信息或对不上都拒绝(fail-closed,防 rebinding 伪造 Host)。\n    const sock = (req as { socket?: { localAddress?: string; localPort?: number } }).socket\n    if (!(sock?.localAddress && sock?.localPort && hostName === sock.localAddress && hostPort === String(sock.localPort))) {\n      writeJson(res, 403, { ok: false, error: '请求的 Host 与本机服务地址不符(可能的 DNS rebinding),已拒绝' })\n      return false\n    }\n  }\n  return true\n}\n\n/** 请求体超过大小上限时抛出,用于映射 413(与 JSON 解析失败的 400 区分)。 */\nclass PayloadTooLargeError extends Error {}\n\n/** 读取并解析 JSON 请求体,带大小上限。非对象载荷(如 `null`)按非法请求体拒绝。 */\nasync function readJsonBody(req: import('node:http').IncomingMessage): Promise<unknown> {\n  const chunks: Buffer[] = []\n  let size = 0\n  for await (const chunk of req) {\n    const buf = typeof chunk === 'string' ? Buffer.from(chunk) : (chunk as Buffer)\n    size += buf.length\n    if (size > MAX_BODY_BYTES) throw new PayloadTooLargeError('请求体超过 256KB 上限')\n    chunks.push(buf)\n  }\n  if (chunks.length === 0) return {}\n  const parsed: unknown = JSON.parse(Buffer.concat(chunks).toString('utf-8'))\n  // JSON `null` / 标量 / 数组都不是合法请求体。必须在此拒绝:否则下游\n  // `if (!body) return` 会把它当成「已应答」直接返回,请求永远挂着不结束。\n  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {\n    throw new Error('请求体必须是 JSON 对象')\n  }\n  return parsed\n}\n\n/** 读取请求体并直接应答解析错误(400/413);成功返回 body,失败返回 undefined(响应已写)。 */\nasync function readBodyOrReply(req: IncomingMessage, res: ServerResponse): Promise<OptimizeRequestBody | undefined> {\n  try {\n    return (await readJsonBody(req)) as OptimizeRequestBody\n  } catch (error) {\n    // 请求体问题是客户端错误(400/413),不是上游模型失败(502)。\n    if (error instanceof PayloadTooLargeError) {\n      writeJson(res, 413, { ok: false, error: error.message })\n    } else {\n      writeJson(res, 400, { ok: false, error: '请求体不是合法的 JSON 对象' })\n    }\n    return undefined\n  }\n}\n\n/** 折叠流式输出为纯文本;finish 为 error/aborted 时抛出,max-tokens 标记截断。onDelta 逐段回调增量(用于 SSE 透传)。 */\nasync function collectText(\n  stream: AsyncIterable<import('@deepseek-ai/dsh-llm').StreamChunk>,\n  onDelta?: (text: string) => void,\n): Promise<{ text: string; truncated: boolean }> {\n  let deltas = ''\n  const blocks = new Map<number, string>()\n  let truncated = false\n  for await (const chunk of stream) {\n    switch (chunk.type) {\n      case 'text-delta':\n        deltas += chunk.text\n        onDelta?.(chunk.text)\n        break\n      case 'block-end':\n        if (chunk.block.type === 'text') blocks.set(chunk.index, chunk.block.text)\n        break\n      case 'finish': {\n        const reason = chunk.reason\n        if (reason.kind === 'error' || reason.kind === 'aborted') {\n          throw new Error(`模型调用失败(${reason.failure.code}): ${reason.failure.message}`)\n        }\n        // 优化调用不带工具,模型请求工具说明路由/适配异常,明确报错而非当成功展示。\n        if (reason.kind === 'tool-calls') {\n          throw new Error('模型意外请求工具调用(优化调用不提供工具),请检查模型路由配置')\n        }\n        if (reason.kind === 'max-tokens') truncated = true\n        break\n      }\n      default:\n        break\n    }\n  }\n  // 优先使用增量(delta 是协议主通道);某些适配器只发 block-end 时降级。\n  const text = deltas || [...blocks.entries()].sort(([a], [b]) => a - b).map(([, t]) => t).join('')\n  return { text, truncated }\n}\n\n/**\n * 推理档位的序数标尺:名字里能读出强度的按序数比较,读不出返回 undefined。\n * 覆盖各适配器常见命名(含 none/off 这类「关掉推理」的档与中英写法)。\n * 从高档往低档匹配,避免 \"xhigh\" 先被 /high/ 截获成普通高档。\n * 英文一律带词边界:否则 \"low\" 会命中 \"follow\"/\"allow\"/\"below\" 这类无关 id。\n */\nconst EFFORT_RANK: readonly { rank: number; re: RegExp }[] = [\n  { rank: 4, re: /(?:^|[^a-z])(?:x[\\s_-]?high|very[\\s_-]?high|maximum|max|highest)(?:$|[^a-z])|最高/i },\n  { rank: 3, re: /(?:^|[^a-z])high(?:$|[^a-z])|高/i },\n  { rank: 2, re: /(?:^|[^a-z])(?:medium|mid(?:dle)?|standard|default)(?:$|[^a-z])|中/i },\n  { rank: 1, re: /(?:^|[^a-z])(?:minimal|minimum|lowest|low)(?:$|[^a-z])|最少|最低|低/i },\n  { rank: 0, re: /(?:^|[^a-z])(?:none|off|disabled|no[\\s_-]?reasoning)(?:$|[^a-z])|^(?:0)$/i },\n]\n\nfunction effortRank(id: string, name: string): number | undefined {\n  for (const { rank, re } of EFFORT_RANK) {\n    if (re.test(id) || re.test(name)) return rank\n  }\n  return undefined\n}\n\n/**\n * 解析指定路由支持的最低推理强度(「最低档」配置用)。\n *\n * 按可读出的强度序数取最小档;读不出序数(适配器用不透明 id)时返回 undefined,\n * 由调用方回退到会话选择——**不再**假设「展示顺序首位即最低档」:个别适配器\n * 高档在前时,那个假设会把优化钳到最慢最贵的一档,与配置意图正好相反。\n * 目录查询失败或模型不支持推理时同样返回 undefined。\n */\nasync function resolveLowestEffort(\n  llm: Context['llm'],\n  provider: string,\n  model: string,\n): Promise<string | undefined> {\n  try {\n    // reasoning 只在精确路由元数据上,listModels 的目录项没有。\n    const efforts = (await llm.resolveModelInfo(provider, model)).reasoning?.efforts\n    if (!efforts?.length) return undefined\n    let best: { id: string; rank: number } | undefined\n    for (const effort of efforts) {\n      const rank = effortRank(String(effort.id), String(effort.name ?? ''))\n      if (rank === undefined) continue\n      if (!best || rank < best.rank) best = { id: String(effort.id), rank }\n    }\n    return best?.id\n  } catch {\n    return undefined\n  }\n}\n\n// 路由 → 最低档 effort 缓存的生存期(实例级,挂在 apply 闭包内,见下)。\nconst EFFORT_CACHE_TTL = 10 * 60 * 1000\n\n/**\n * 模型路由解析:设置里固定的 'provider/model' → 请求方会话当前选择 → 第一个可用路由。\n * 空字符串视为未设置;provider 路由键不含 '/',模型 id 可以含。无可用路由时返回 undefined。\n */\nasync function resolveRoute(\n  llm: Context['llm'],\n  pinnedModel: string | undefined,\n  bodyProvider: string | undefined,\n  bodyModel: string | undefined,\n): Promise<{ provider: string; model: string } | undefined> {\n  let provider: string | undefined\n  let model: string | undefined\n  const pinned = asOptionalString(pinnedModel)\n  if (pinned) {\n    const slash = pinned.indexOf('/')\n    if (slash > 0 && slash < pinned.length - 1) {\n      provider = pinned.slice(0, slash)\n      model = pinned.slice(slash + 1)\n    }\n  }\n  provider ??= bodyProvider\n  model ??= bodyModel\n  if (!provider || !model) {\n    const first = llm.listProviders()[0]\n    if (!provider && first) provider = first.id\n    if (provider && !model) {\n      try {\n        model = (await llm.listModels(provider))[0]?.id\n      } catch {\n        // 目录查询失败不代表路由不可用,留空往下走到明确报错。\n      }\n    }\n  }\n  return provider && model ? { provider, model } : undefined\n}\n\n/** HTTP 载体服务的最小依赖面(webServer / httpServer 两个名字共用同一形状)。 */\ninterface WebRouteService {\n  register(route: {\n    kind: 'exact' | 'prefix'\n    path: string\n    handler: (req: IncomingMessage, res: ServerResponse) => void | Promise<void>\n  }): () => void\n}\n\nexport function apply(ctx: Context, config: Config) {\n  // R27 告警去重集合(实例级,见 warnUnknownEnum 注释)。\n  const warnedConfigValues = new Set<string>()\n  // 在途优化计数(并发防线,见 MAX_CONCURRENT_OPTIMIZES)。\n  let inFlightOptimizes = 0\n  // 路由 → 最低档 effort 的实例级缓存:每次优化点击都会解析一遍,而模型的推理\n  // 档位表极少变化。仅缓存成功结果,失败不缓存——下次点击重试,避免一次目录\n  // 抖动永久挡住钳档。挂在 apply 闭包内:随插件实例生灭,测试间天然隔离。\n  const effortCache = new Map<string, { effort: string; at: number }>()\n  const resolveLowestEffortCached = async (llm: Context['llm'], provider: string, model: string): Promise<string | undefined> => {\n    const key = `${provider}/${model}`\n    const hit = effortCache.get(key)\n    if (hit && Date.now() - hit.at < EFFORT_CACHE_TTL) return hit.effort\n    const effort = await resolveLowestEffort(llm, provider, model)\n    if (effort !== undefined) effortCache.set(key, { effort, at: Date.now() })\n    return effort\n  }\n\n  // 设置页命名空间:组合层配置作为 base,用户在 设置→插件配置 中的修改实时生效。\n  // 按能力探测分派,保证同一份构建跨版本:\n  //  - 0.2.0 起 ctx.settings 是 SettingsForms:按插件导出的 Config schema 自动\n  //    生成配置表单(namespace = 组合行 id)。volatile 字段经引用 cell 原位更新,\n  //    插件不重挂载——current() 在读取时展开 cell 即可,无需注册命名空间。\n  //    这里同时关闭宿主的原生自动表单(auto:false),避免与设置卡重复;\n  //  - settings.installSection 是函数(0.1.2-alpha.5+ / 0.1.2-rc.1)→ 新 API;\n  //  - 否则(0.1.0-rc.x / 0.1.1-rc.x)→ 旧独立函数的等价内联\n  //    (register{base} + setSource + watch + 卸载回落 entry,对照 0.1.0-rc.7 实现);\n  //  - settings 服务整体缺席 → current 保持组合层配置,行为与更早版本一致。\n  let current = (): Config => readConfig(config)\n  ctx.inject(['settings'], (sctx) => {\n    const settings = (sctx as unknown as {\n      settings?: {\n        configure?: (presentation: { auto?: boolean }, owner?: unknown) => () => void\n        installSection?: (c: Context, ns: string, schema: SettingsSchemaLike, base: Config, hooks: SettingsHooks) => void\n        register?: (ns: string, schema: SettingsSchemaLike, opts: { base: Config }) => { get(): Config; watch(fn: () => void): () => void }\n      }\n    }).settings\n    if (!settings) return\n    if (typeof settings.configure === 'function') {\n      // 0.2.x:声明本插件自带设置卡。`auto:false` 在 0.2.0 的语义是「关闭宿主按\n      // Config schema 自动生成的原生表单页」;0.2.1 起该页已无客户端消费方\n      // (全库只剩 schema 字段定义,没有任何 UI 读取 autoGenerate),所以这条调用\n      // 现在只作**显式意图声明**:告诉宿主这个插件自己渲染设置面。保留它让两代\n      // 宿主行为一致,未来若恢复消费方语义也仍然正确。\n      ctx.effect(() => settings.configure!({ auto: false }, (ctx as unknown as { fiber?: unknown }).fiber))\n    }\n    if (typeof settings.installSection === 'function') {\n      settings.installSection(ctx, NS, Config, config, {\n        setSource: (source) => {\n          current = () => readConfig(source())\n        },\n        onChange: () => {},\n      })\n      return\n    }\n    if (typeof settings.register !== 'function') return // 0.2.0:配置由 volatile cell 承载\n    const scope = settings.register(NS, Config, { base: config })\n    current = () => readConfig(scope.get())\n    const disposeWatch = scope.watch(() => {\n      current = () => readConfig(scope.get())\n    })\n    ctx.effect(() => () => {\n      disposeWatch()\n      current = () => readConfig(config)\n    })\n  })\n  // 启动即对初始配置做一次非法枚举告警;请求期配置可能被实时改写,handler 内还会复查。\n  warnUnknownEnumConfig(warnedConfigValues, current())\n\n  // 路由挂载状态。mounted 必须**同步**置位:webServer 与 httpServer 若同时存在\n  // (哪怕是两个不同对象),两个 inject 回调都会触发,只有同步标志能挡住第二次\n  // 注册——按对象身份比较会漏挡,导致路由被注册两遍。\n  // 同时它随 effect 生命周期复位:服务 dispose→re-register 时 inject 回调再次\n  // 触发,能重新挂载,而不是从此缺席到插件整体重载。\n  let mounted = false\n  const mount = (server: WebRouteService | undefined) => {\n    if (!server || mounted) return\n    mounted = true\n    ctx.effect(() => {\n      const disposeOptimize = server.register({ kind: 'exact', path: ROUTE_PATH, handler })\n      const disposeTest = server.register({ kind: 'exact', path: TEST_ROUTE_PATH, handler: testHandler })\n      console.log(`[${name}] loaded, POST ${ROUTE_PATH}`)\n      return () => {\n        mounted = false\n        disposeOptimize()\n        disposeTest()\n      }\n    })\n  }\n  ctx.inject(['webServer'], (sctx) => mount((sctx as unknown as { webServer?: WebRouteService }).webServer))\n  ctx.inject(['httpServer'], (sctx) => mount((sctx as unknown as { httpServer?: WebRouteService }).httpServer))\n  ctx.effect(() => {\n    const timer = setTimeout(() => {\n      if (!mounted) {\n        console.error(`[${name}] 未找到 webServer/httpServer 服务,路由未注册——当前 dsh 版本可能不兼容`)\n      }\n    }, 10_000)\n    return () => clearTimeout(timer)\n  })\n\n  async function handler(req: IncomingMessage, res: ServerResponse) {\n      if (req.method !== 'POST') {\n        writeJson(res, 405, { ok: false, error: 'Method Not Allowed' })\n        return\n      }\n      if (!assertTrustedOrigin(req, res)) return\n      // 并发防线:在途优化已达上限时直接 429(每次调用都是真实计费调用)。\n      // 计数在下方 try/finally 里配对释放,任何路径(含提前 return)都不会泄漏。\n      if (inFlightOptimizes >= MAX_CONCURRENT_OPTIMIZES) {\n        writeJson(res, 429, {\n          ok: false,\n          error: `同时进行的优化已达上限(${MAX_CONCURRENT_OPTIMIZES} 个),请稍后再试。`,\n        })\n        return\n      }\n      inFlightOptimizes += 1\n      try {\n        await handleOptimize(req, res)\n      } finally {\n        inFlightOptimizes -= 1\n      }\n  }\n\n  async function handleOptimize(req: IncomingMessage, res: ServerResponse) {\n      // 客户端在响应结束前断开连接时,中止模型调用。\n      // 注意:必须用 res 的 close;req 的 close 在请求体读完就会触发,不代表断连。\n      const abort = new AbortController()\n      res.on('close', () => {\n        if (!res.writableEnded) abort.abort()\n      })\n\n      try {\n        const body = await readBodyOrReply(req, res)\n        if (!body) return\n        const text = asOptionalString(body.text)\n        // 会话标注:客户端带来的会话 id(发起优化的会话)优先;缺席(旧版宿主\n        // 槽位不投递 sessionId、CLI 直调等)回落合成 id——标注恒存在,保证\n        // opencode 等要求会话头的提供方在任何路径上都能路由成功。\n        const sessionId = asOptionalString(body.sessionId) ?? ONESHOT_SESSION_ID\n        if (!text) {\n          writeJson(res, 400, { ok: false, error: '提示词内容为空' })\n          return\n        }\n\n        const cfg = current()\n        // 宽松 schema 的配套归一化:未知枚举值一律回落默认,保证旧版设置文档可用\n        //(非法值会先告警一次,见 warnUnknownEnumConfig)。\n        warnUnknownEnumConfig(warnedConfigValues, cfg)\n        const language: OutputLanguage = cfg.language === 'en' ? 'en' : 'zh'\n        const mode: OptimizerMode = cfg.mode === 'fast' ? 'fast' : 'full'\n        const route = await resolveRoute(ctx.llm, cfg.model, asOptionalString(body.provider), asOptionalString(body.model))\n        if (!route) {\n          writeJson(res, 409, {\n            ok: false,\n            error: '未找到可用模型:请先在 设置 → 模型 中配置提供方,或在 设置的插件页「提示词优化」 中固定一个模型',\n          })\n          return\n        }\n        // 回退模型链:设置里配了 fallbackModel('provider/model')时追加一条备用路由。\n        // 仅当某次尝试还没向客户端推送过任何 delta 就失败时才换路由重试——\n        // 客户端已经看到部分内容后再换路由,输出会变成两个模型的拼接。\n        const routes = [route]\n        const fallbackRaw = asOptionalString(cfg.fallbackModel)\n        if (fallbackRaw) {\n          const slash = fallbackRaw.indexOf('/')\n          if (slash > 0 && slash < fallbackRaw.length - 1) {\n            const fb = { provider: fallbackRaw.slice(0, slash), model: fallbackRaw.slice(slash + 1) }\n            if (fb.provider !== route.provider || fb.model !== route.model) routes.push(fb)\n          }\n        }\n\n        // 设置里关掉「携带上下文」时,即使客户端带了 context 也忽略(Host 侧硬开关)。\n        const context = cfg.includeContext === false ? undefined : parseContextInput(body.context)\n        // 轻量记忆链:上一轮优化结果,截断到 1500 字符(它只是延续参考,不是优化对象)。\n        // 与 context 一样跟随「携带上下文」开关——关闭后不带任何会话衍生材料。\n        const previousRaw = cfg.includeContext === false ? undefined : asOptionalString(body.previous)\n        const previous = previousRaw ? (previousRaw.length > 1500 ? `${previousRaw.slice(0, 1500)}…` : previousRaw) : undefined\n        // 0.2.0 把消息源联合收窄为 user/model/tool/system-prompt,但运行时按\n        // merge-extensible 容忍未知源(插件署名仍是最直接的审计信息);保留\n        // kind:'plugin' 形状,以结构断言跨过两代类型定义。\n        const message = {\n          id: `prompt-optimizer-${crypto.randomUUID()}`,\n          role: 'user',\n          content: [{ type: 'text', text: buildUserPayload(text, language, context, previous) }],\n          source: { kind: 'plugin', plugin: name },\n        } as unknown as Message\n        // 策略分叉:有上下文走「提炼目的 + 润色」(不套模板),无上下文走「结构模板」改写。\n        const system = buildSystemPrompt(language, mode, context?.length ? 'intent' : 'template')\n        // 输出上限跟随输入长度:优化结果体量与草稿正相关(完整模式还多一段分析),\n        // 长草稿撞固定上限会被截断。取配置值与「输入估算 × 模式系数」的较大者,32768 封顶。\n        const maxTokens =\n          cfg.autoMaxTokens === false\n            ? cfg.maxTokens\n            : Math.min(32768, Math.max(cfg.maxTokens, Math.ceil(estimateTokens(text) * (mode === 'fast' ? 1.5 : 2))))\n        // 推理强度:默认钳到该模型支持的最低档(优化是格式化元任务,高推理只会拉长\n        // 首 token 前的空等),按路由逐次解析;仅显式配置 'session' 时透传会话选择。\n        // 无法确定最低档(目录失败/模型不暴露推理)时回退到会话值,不冒险乱发。\n        const sessionEffort = asOptionalString(body.reasoningEffort)\n        // 宽松 schema 的配套归一化:仅 'session' 视为跟随会话,其余(含缺省)都钳最低档。\n        const preferSessionEffort = cfg.reasoningEffort === 'session'\n\n        // 阶段二:流式响应。delta 逐段推送(SSE),done 携带最终解析结果;\n        // 此阶段响应头已发出,模型错误也走事件通道,无法再改状态码。\n        res.writeHead(200, {\n          'content-type': 'text/event-stream; charset=utf-8',\n          'cache-control': 'no-cache, no-transform',\n          'x-accel-buffering': 'no',\n        })\n        const send = (event: Record<string, unknown>) => {\n          if (!res.destroyed && !res.writableEnded) res.write(`data: ${JSON.stringify(event)}\\n\\n`)\n        }\n        // SSE 心跳:首 token 前可能长时间无字节,反代/隧道会按空闲超时掐连接。\n        // 注释帧(`:` 开头)被现有客户端解析器忽略(它只认 `data:` 行)。\n        const heartbeat = setInterval(() => {\n          if (!res.destroyed && !res.writableEnded) res.write(': ping\\n\\n')\n        }, SSE_HEARTBEAT_MS)\n        // 超时兜底:模型挂死时中止调用并通知客户端(timedOut 与客户端断连共用 abort,靠标志位区分)。\n        const timeoutSec = cfg.timeoutSeconds ?? 120\n        let timedOut = false\n        const timer = setTimeout(() => {\n          timedOut = true\n          abort.abort()\n        }, timeoutSec * 1000)\n        try {\n          let sentAny = false\n          let used = routes[0]\n          let raw: { text: string; truncated: boolean } | null = null\n          let lastError: unknown = null\n          // O12:主路由零产出失败而启用回退时,把失败原因带给客户端(徽章 tooltip 展示)。\n          let fallbackReason: string | undefined\n          for (const attempt of routes) {\n            used = attempt\n            try {\n              const options: GenerateOptions = {\n                provider: attempt.provider,\n                model: attempt.model,\n                system,\n                messages: [message],\n                maxTokens,\n                temperature: cfg.temperature ?? 0.2,\n                signal: abort.signal,\n                // 会话标注恒存在:客户端会话 id 优先(会话级计量正确归属),\n                // 缺席回落合成 id。opencode 等提供方要求会话头(x-opencode-session,\n                // 由 pi-ai 适配器按 GenerateOptions.sessionId 注入),缺失会被\n                // API 以「缺少请求头」拒绝;其余适配器仅作模型不可见的传输\n                // 元数据处理,不外发。\n                sessionId: sessionId as GenerateOptions['sessionId'],\n              }\n              let effort = sessionEffort\n              if (!preferSessionEffort) {\n                effort = (await resolveLowestEffortCached(ctx.llm, attempt.provider, attempt.model)) ?? sessionEffort\n              }\n              if (effort) {\n                options.reasoningEffort = effort as GenerateOptions['reasoningEffort']\n              }\n              // 思考块过滤:推理模型把 <think>…</think> 当正文输出(内含复述的\n              // 标记字样),剥掉后客户端的实时预览与最终解析都只见到真实内容。\n              const thinkFilter = createThinkFilter()\n              raw = await collectText(ctx.llm.stream(options), (delta) => {\n                sentAny = true\n                const clean = thinkFilter.push(delta)\n                if (clean) send({ type: 'delta', text: clean })\n              })\n              const thinkTail = thinkFilter.flush()\n              if (thinkTail) send({ type: 'delta', text: thinkTail })\n              lastError = null\n              break\n            } catch (error) {\n              lastError = error\n              if (timedOut || abort.signal.aborted || sentAny) break\n              if (attempt !== routes[routes.length - 1]) {\n                fallbackReason = error instanceof Error ? error.message : String(error)\n                console.error(`[${name}] 主路由 ${attempt.provider}/${attempt.model} 失败,尝试回退路由:`, error)\n              }\n            }\n          }\n          if (raw) {\n            const parsed = parseOptimizerOutput(raw.text, mode)\n            send({\n              type: 'done',\n              ...parsed,\n              truncated: raw.truncated,\n              provider: used.provider,\n              model: used.model,\n              fallbackUsed: used !== routes[0],\n              ...(fallbackReason ? { fallbackReason } : {}),\n            })\n          } else if (timedOut) {\n            send({\n              type: 'error',\n              error: `优化超时:${timeoutSec} 秒内未生成完毕。可在 设置的插件页「提示词优化」 中调高「超时时间」。`,\n            })\n          } else if (!abort.signal.aborted && lastError) {\n            const message = lastError instanceof Error ? lastError.message : String(lastError)\n            console.error(`[${name}] optimize failed:`, lastError)\n            send({ type: 'error', error: message })\n          }\n        } finally {\n          clearTimeout(timer)\n          clearInterval(heartbeat)\n        }\n        res.end()\n      } catch (error) {\n        if (abort.signal.aborted) return // 客户端已断开,无需应答\n        const message = error instanceof Error ? error.message : String(error)\n        console.error(`[${name}] optimize failed:`, error)\n        // SSE 阶段(res.writeHead(200) 之后)出错时不能再改状态码:writeJson 内部\n        // 已按 headersSent 跳过,这里只是避免调用方误以为已应答。\n        writeJson(res, 502, { ok: false, error: message })\n        if (!res.writableEnded) res.end()\n      }\n  }\n\n  /** 模型连通性测试:按同一套路由解析发一个 32 token 封顶的探活调用,20s 超时。结果(含失败)一律 200 返回,ok 标志区分。 */\n  async function testHandler(req: IncomingMessage, res: ServerResponse) {\n    if (req.method !== 'POST') {\n      writeJson(res, 405, { ok: false, error: 'Method Not Allowed' })\n      return\n    }\n    if (!assertTrustedOrigin(req, res)) return\n    const body = await readBodyOrReply(req, res)\n    if (!body) return\n    const cfg = current()\n    const route = await resolveRoute(ctx.llm, cfg.model, asOptionalString(body.provider), asOptionalString(body.model))\n    if (!route) {\n      writeJson(res, 409, {\n        ok: false,\n        error: '未找到可用模型:请先在 设置 → 模型 中配置提供方,或在 设置的插件页「提示词优化」 中固定一个模型',\n      })\n      return\n    }\n    const abort = new AbortController()\n    res.on('close', () => {\n      if (!res.writableEnded) abort.abort()\n    })\n    let timedOut = false\n    const timer = setTimeout(() => {\n      timedOut = true\n      abort.abort()\n    }, 20_000)\n    const started = Date.now()\n    try {\n      // 同上:插件署名的消息源以结构断言跨版本。\n      const message = {\n        id: `prompt-optimizer-test-${crypto.randomUUID()}`,\n        role: 'user',\n        content: [{ type: 'text', text: 'ping' }],\n        source: { kind: 'plugin', plugin: name },\n      } as unknown as Message\n      const result = await collectText(\n        ctx.llm.stream({\n          provider: route.provider,\n          model: route.model,\n          messages: [message],\n          maxTokens: 32,\n          signal: abort.signal,\n          // 探活没有真实会话,标注一个固定合成 id:opencode 等提供方要求\n          // 会话头(x-opencode-session,适配器按 sessionId 注入),缺失会被\n          // API 以「缺少请求头」拒绝;固定值让探活稳定路由到同一桶。\n          sessionId: 'prompt-optimizer-connectivity-test' as GenerateOptions['sessionId'],\n        }),\n      )\n      writeJson(res, 200, {\n        ok: true,\n        provider: route.provider,\n        model: route.model,\n        latencyMs: Date.now() - started,\n        reply: result.text.slice(0, 80),\n      })\n    } catch (error) {\n      if (timedOut) {\n        writeJson(res, 200, { ok: false, error: '连接测试超时(20s 无响应)' })\n      } else if (!abort.signal.aborted) {\n        writeJson(res, 200, { ok: false, error: error instanceof Error ? error.message : String(error) })\n      }\n    } finally {\n      clearTimeout(timer)\n    }\n  }\n}\n"
    },
    {
      "path": "src/client/controller.ts",
      "content": "// 0.1.2 起 dsh-client-runtime 已并包移除,ClientContext 即 cordis 的 Context。\r\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\r\nimport type { SessionId } from '@deepseek-ai/dsh-client-connection/client'\r\nimport type { OptimizerHistoryEntry, OptimizerSessionHistoryRecord } from './host-faces.js'\r\nimport { legacyQueryFace, sessionEventEntries, type ModelDirectoriesLike } from './host-faces.js'\r\nimport { capConversationContext, compactPartialBuffer, parsePartialOptimizerOutput, type ConversationTurn } from '../prompt.js'\r\n\r\nexport interface OptimizeResult {\r\n  analysis: string\r\n  optimized: string\r\n  wellFormed: boolean\r\n  truncated: boolean\r\n  provider: string\r\n  model: string\r\n  /** 主路由失败、实际由回退路由产出时为 true。 */\r\n  fallbackUsed: boolean\r\n  /** O12:触发回退的主路由失败原因(回退未发生时为空),用于徽章 tooltip。 */\r\n  fallbackReason?: string\r\n  /** 从点击到 done 的客户端实测耗时(毫秒),含会话查询与排队等待。 */\r\n  durationMs?: number\r\n}\r\n\r\nexport interface OptimizerState {\r\n  open: boolean\r\n  /** cancelled = loading 中被用户取消(O2):面板保持打开,冻结展示已生成的部分。 */\r\n  status: 'idle' | 'loading' | 'done' | 'error' | 'cancelled'\r\n  error: string | null\r\n  result: OptimizeResult | null\r\n  /** 流式进行中的分段实况,仅 loading/cancelled 期间有值(cancelled 时为取消瞬间的定格)。 */\r\n  live: { analysis: string; optimized: string } | null\r\n  /** 最近一次成功发起的请求,供「重新优化」复用;prefix 为斜杠命令前缀(替换时拼回)。 */\r\n  last: { text: string; sessionId: SessionId; prefix?: string } | null\r\n  /** 「替换输入框」后的撤回依据:替换前的原文 + 替换后的文本(用于检测用户编辑)。 */\r\n  applied: { backup: string; text: string } | null\r\n}\r\n\r\nconst ROUTE = '/dsh-prompt-optimizer/optimize'\r\n\r\nconst INITIAL: OptimizerState = { open: false, status: 'idle', error: null, result: null, live: null, last: null, applied: null }\r\n\r\n/**\r\n * 拆斜杠命令前缀:「/goal 帮我……」只优化正文,替换时拼回前缀,避免命令词被改写。\r\n * 正文为空(只敲了命令,如 \"/goal\")时返回 commandOnly:true,调用方直接提示、\r\n * 不发请求(O11:把命令词本身拿去优化只会得到垃圾输出);不像命令(如 /path/to/file)不拆。\r\n */\r\nexport function splitCommandPrefix(text: string): { prefix?: string; body: string; commandOnly?: boolean } {\r\n  const trimmed = text.trim()\r\n  const match = /^(\\/[A-Za-z][\\w-]*)(?:\\s+([\\s\\S]+))?$/.exec(trimmed)\r\n  if (!match) return { body: trimmed }\r\n  if (!match[2] || !match[2].trim()) return { body: trimmed, commandOnly: true }\r\n  return { prefix: match[1], body: match[2].trim() }\r\n}\r\n\r\n/**\r\n * 把 `last` 里拆分存储的「前缀 + 正文」拼回完整输入(retry 复用路径)。\r\n * 前缀与正文之间用单个空格分隔,与 splitCommandPrefix 的识别形状一致。\r\n */\r\nexport function joinLast(last: { text: string; prefix?: string }): string {\r\n  return last.prefix ? `${last.prefix} ${last.text}` : last.text\r\n}\r\n\r\n/**\r\n * 发送即关闭面板的判定(纯函数,便于测试)。四条信号任一命中即认为消息已发出:\r\n * 发送阶段(0.2.2 起 `phase:'sending'`,宿主确认接收前草稿仍保留)、\r\n * 草稿被清空(宿主确认接收后的直发/入队,用户手动清空同理——面板引用的草稿已不存在)、\r\n * 会话开始运行(直发)、队列变长(忙时入队)。\r\n * loading(优化中)期间一律不关:发送/清空不应误中止在跑的优化,取消走 Esc。\r\n * 旧宿主(0.1.x / 0.2.0 / 0.2.1)的 phase 只有前四个值,不含 'sending',天然不触发。\r\n */\r\nexport function shouldAutoClose(input: {\r\n  open: boolean\r\n  status: 'idle' | 'loading' | 'done' | 'error' | 'cancelled'\r\n  draft: string\r\n  /** 0.2.2+ 的提交阶段;旧宿主不含 'sending',不参与新判定。 */\r\n  phase?: string\r\n  prevRunning: boolean\r\n  running: boolean\r\n  prevQueued: number\r\n  queued: number\r\n}): boolean {\r\n  if (!input.open || input.status === 'loading') return false\r\n  return (\r\n    input.phase === 'sending' ||\r\n    !input.draft.trim() ||\r\n    (!input.prevRunning && input.running) ||\r\n    input.queued > input.prevQueued\r\n  )\r\n}\r\n\r\n/** 摊平 content blocks 为纯文本(图片等非文本块对优化意图无帮助,忽略)。 */\r\nfunction flattenText(content: unknown): string {\r\n  if (!Array.isArray(content)) return ''\r\n  return content\r\n    .map((block) =>\r\n      block && typeof block === 'object' && (block as { type?: unknown }).type === 'text'\r\n        ? String((block as { text?: unknown }).text ?? '')\r\n        : '',\r\n    )\r\n    .filter(Boolean)\r\n    .join('\\n')\r\n    .trim()\r\n}\r\n\r\n/**\r\n * 上下文取样:用户消息优先保底。真实 agentic 会话里最近的消息往往是成串的\r\n * assistant 步骤碎片(实测一个 30 条消息的会话只有 5 条用户消息),纯按时间取\r\n * 最近 N 条会把用户的真实诉求挤出上下文。取「最近 4 条用户消息 + 最近 4 条助手\r\n * 回复」按原始顺序合并(总量 ≤8,不再触发条数裁剪),再交预算收敛。\r\n */\r\nfunction sampleContextTurns(turns: ConversationTurn[]): ConversationTurn[] {\r\n  const users = turns.map((t, i) => ({ t, i })).filter((x) => x.t.role === 'user').slice(-4)\r\n  const assistants = turns.map((t, i) => ({ t, i })).filter((x) => x.t.role === 'assistant').slice(-4)\r\n  const merged = [...users, ...assistants].sort((a, b) => a.i - b.i).map((x) => x.t)\r\n  return capConversationContext(merged)\r\n}\r\n\r\n/**\r\n * 从 session.history 事件页提取优化上下文:真实用户输入(user/message 且\r\n * source.kind 为 'user',排除插件/系统注入的 user 角色消息)+ 助手回复\r\n * (assistant/message,跳过只承载 usage 的空壳消息)。返回按时间升序,\r\n * 已按共享预算收敛(用户消息保底 4 条,总量 ≤8 条 / 1600 字符)。\r\n */\r\nexport function extractContextTurns(entries: readonly (OptimizerHistoryEntry | OptimizerSessionHistoryRecord)[]): ConversationTurn[] {\r\n  const turns: ConversationTurn[] = []\r\n  for (const entry of entries) {\r\n    const event = entry?.event\r\n    if (!event || typeof event !== 'object') continue\r\n    if (event.type === 'user/message') {\r\n      const data = event.data as { source?: { kind?: unknown }; content?: unknown }\r\n      if (data?.source?.kind !== 'user') continue\r\n      const text = flattenText(data.content)\r\n      if (text) turns.push({ role: 'user', text })\r\n    } else if (event.type === 'assistant/message') {\r\n      const data = event.data as { message?: { content?: unknown } }\r\n      const text = flattenText(data?.message?.content)\r\n      if (text) turns.push({ role: 'assistant', text })\r\n    }\r\n  }\r\n  return sampleContextTurns(turns)\r\n}\r\n\r\n/**\r\n * 按钮(conversation.input.right)与结果面板(conversation.input.dock)\r\n * 共享的状态容器:apply 闭包内创建,两个槽位组件各自 useSyncExternalStore 订阅。\r\n * opts.isModelPinned:设置里固定了模型时返回 true(Host 固定值优先,\r\n * 会话模型查询的结果反正用不上,跳过可省一次 RPC 往返)。\r\n * opts.isContextEnabled:设置里关闭「携带上下文」时返回 false,\r\n * 跳过会话历史查询;默认开启。\r\n */\r\nexport function createOptimizerController(\r\n  ctx: ClientContext,\r\n  opts: {\r\n    isModelPinned?: () => boolean\r\n    isContextEnabled?: () => boolean\r\n    /** 快速模式(与 Host 归一化口径一致:仅 mode==='fast' 为真)。决定无标记流是否可直接预览。 */\r\n    isFastMode?: () => boolean\r\n    /**\r\n     * R21 客户端超时看门狗的总时长(毫秒)。由入口按设置里的 timeoutSeconds 计算\r\n     * (设置秒数 × 1000 + 5s 余量);缺省 125s。看门狗兜底 Host 挂死/网络黑洞——\r\n     * 正常情况下 Host 会先到超时并以 error 事件返回更友好的文案。\r\n     */\r\n    getWatchdogMs?: () => number\r\n    /**\r\n     * 会话模型目录服务读取器(可选)。由入口经**独立的可选 inject** 捕获\r\n     * `ctx.modelDirectories`(不能并进主 inject,否则旧版宿主会让客户端永远\r\n     * 等不到就绪),在点击时惰性读取;缺席返回 undefined,走 Host 回退解析。\r\n     */\r\n    getSessionModelDirectories?: () => ModelDirectoriesLike | undefined\r\n    /**\r\n     * 会话服务读取器(`ctx.sessions`,可选)。用于从会话事件窗口取近期对话作为\r\n     * 优化上下文——0.2.x 上这是唯一能读到既有历史的公开面(见 host-faces\r\n     * `sessionEventEntries` 的说明)。缺席时退回 legacy 查询面 / 按无上下文降级。\r\n     */\r\n    getSessions?: () => unknown\r\n  } = {},\r\n) {\r\n  let state: OptimizerState = INITIAL\r\n  const listeners = new Set<() => void>()\r\n  let abort: AbortController | null = null\r\n  // 流式实况的合帧缓冲:delta 碎(实测 2 字符一帧),每帧都 set 会让面板\r\n  // 整树重渲染数千次。攒 50ms 刷一次,人眼无感、滚动不卡。\r\n  let liveRaw = ''\r\n  // R14:压缩把已定格的段落移出缓冲(压缩后解析不出),定格值在此持有:\r\n  // 分析段(旧顺序:OPTIMIZED 确认时定格)与优化稿段(新顺序:ANALYSIS\r\n  // 确认时定格)。每次请求开始时清零。\r\n  let frozenAnalysis = ''\r\n  let frozenOptimized = ''\r\n  let liveTimer: ReturnType<typeof setTimeout> | null = null\r\n\r\n  const clearLiveTimer = () => {\r\n    if (liveTimer) {\r\n      clearTimeout(liveTimer)\r\n      liveTimer = null\r\n    }\r\n  }\r\n\r\n  const set = (patch: Partial<OptimizerState>) => {\r\n    state = { ...state, ...patch }\r\n    for (const listener of listeners) listener()\r\n  }\r\n\r\n  async function optimize(text: string, sessionId: SessionId) {\r\n    // 斜杠命令只优化正文;前缀记入 last,「替换输入框」时拼回(ResultDock 负责)。\r\n    const split = splitCommandPrefix(text)\r\n    const { prefix, body: draft } = split\r\n    if (!draft || state.status === 'loading') return\r\n    // O11:只有命令没有正文——把命令词拿去优化只会得到垃圾输出,直接提示不发请求。\r\n    if (split.commandOnly) {\r\n      set({\r\n        open: true,\r\n        status: 'error',\r\n        error: '检测到斜杠命令但没有正文:请先输入要优化的内容。',\r\n        live: null,\r\n        last: { text: draft, sessionId },\r\n      })\r\n      return\r\n    }\r\n    // 轻量记忆链:同一会话已有优化结果、且本轮草稿较上轮发生了变化(用户在我们\r\n    // 的产物上继续编辑)时,把上轮结果作为延续参考传给模型;发送即关闭面板会清掉\r\n    // result,记忆链自然归零。同文重试(retry)不带——那是重新生成,不是迭代。\r\n    // 跟随「携带上下文」开关:关闭后不带任何会话衍生材料;上轮格式退化\r\n    // (wellFormed=false,可能混入多余文字)的结果也不传,避免噪声延续。\r\n    // 注意:必须在下面 set(loading) 之前读旧 state。\r\n    const previous =\r\n      state.result &&\r\n      state.result.wellFormed &&\r\n      state.last?.sessionId === sessionId &&\r\n      state.last.text !== draft &&\r\n      (opts.isContextEnabled?.() ?? true)\r\n        ? state.result.optimized\r\n        : undefined\r\n    abort?.abort()\r\n    clearLiveTimer()\r\n    liveRaw = ''\r\n    frozenAnalysis = ''\r\n    frozenOptimized = ''\r\n    const controller = new AbortController()\r\n    abort = controller\r\n    // R21 客户端超时看门狗:Host 进程挂死或网络黑洞时,SSE 可能永远不返回首字节,\r\n    // 客户端不能无限转圈。超时触发 abort 并落 error;用户主动取消走 cancel()/close()。\r\n    const watchdogMs = Math.max(1_000, opts.getWatchdogMs?.() ?? 125_000)\r\n    let clientTimedOut = false\r\n    const watchdog = setTimeout(() => {\r\n      clientTimedOut = true\r\n      controller.abort()\r\n    }, watchdogMs)\r\n    // 看门狗触发的超时落明确错误(fetch 抛异常与读流静默结束两条路都要覆盖);\r\n    // 用户主动取消/关闭的状态由 cancel()/close() 负责。\r\n    const failTimeout = () => {\r\n      clearLiveTimer()\r\n      const seconds = Math.round(watchdogMs / 1000)\r\n      set({\r\n        status: 'error',\r\n        live: null,\r\n        error: `请求超时(客户端 ${seconds} 秒无响应,Host 可能未运行)。可在 设置的插件页「提示词优化」 中调高「超时时间」。`,\r\n      })\r\n    }\r\n    // 从点击起计时(含会话查询与首 token 前的等待),done 时记入 result 展示。\r\n    const startedAt = Date.now()\r\n    set({ open: true, status: 'loading', error: null, live: { analysis: '', optimized: '' }, last: { text: draft, sessionId, prefix }, applied: null })\r\n    try {\r\n      // 复用当前会话的模型选择(每次点击实时查询,会话里换模型立即生效);\r\n      // 查询失败时交给 Host 端回退解析。设置里固定了模型时跳过:Host 端\r\n      // 固定值优先,查询结果用不上,省一次 RPC 往返。\r\n      // 会话近期对话作为优化上下文(避免脱离语境「南辕北辙」);与模型查询\r\n      // 相互独立,并行拉取,各自失败各自降级,不阻塞主流程。\r\n      const [selection, context] = await Promise.all([\r\n        (async (): Promise<{ provider?: string; model?: string; reasoningEffort?: string } | undefined> => {\r\n          if (opts.isModelPinned?.()) return undefined\r\n          try {\r\n            // 官方会话模型目录服务(dsh-client-ui-model-selection)与 /model 弹窗\r\n            // 共用同一份目录:`current` 即该会话实际将使用的模型(会话内持久\r\n            // 选择,回落宿主默认)。服务缺席(旧版宿主)时走 Host 回退。\r\n            const directories = opts.getSessionModelDirectories?.()\r\n            if (!directories) {\r\n              console.warn('[dsh-prompt-optimizer] 会话模型目录服务在当前 dsh 版本缺席,改用 Host 回退')\r\n              return undefined\r\n            }\r\n            const state = await directories.directoryFor(sessionId).load()\r\n            const current = state.current\r\n            if (current?.provider && current.model) {\r\n              return { provider: current.provider, model: current.model, reasoningEffort: current.reasoningEffort }\r\n            }\r\n            console.warn('[dsh-prompt-optimizer] 会话没有可用的模型选择,改用 Host 回退:', state.error ?? current)\r\n          } catch (cause) {\r\n            console.warn('[dsh-prompt-optimizer] 会话模型查询失败,改用 Host 回退:', cause)\r\n          }\r\n          return undefined\r\n        })(),\r\n        (async (): Promise<ConversationTurn[] | undefined> => {\r\n          if (!(opts.isContextEnabled?.() ?? true)) return undefined\r\n          // 历史读取先走 0.2.x 的本地事件窗口(ctx.sessions.binding().eventSource),\r\n          // 再退回更早宿主上探测过的 legacy connection.api.sessions.history。\r\n          // 窗口里已由宿主灌入尾部页(500 条 / 至少 2 个 turn / 50 条消息),\r\n          // 足够采样最近 4 条用户输入(见 sampleContextTurns)。\r\n          try {\r\n            const entries = sessionEventEntries(opts.getSessions?.(), sessionId)\r\n            if (entries?.length) {\r\n              const turns = extractContextTurns(entries)\r\n              if (turns.length) return turns\r\n              // 窗口有内容但榨不出可用的 user/assistant 对话(例如只有 transient\r\n              // 实时块、或全是 runtime-context 注入)。**继续**往下降级,不能在这里\r\n              // 直接 return undefined——那会让下面的 legacy 分支变成死代码。\r\n              console.warn('[dsh-prompt-optimizer] 会话事件窗口里没有可用的对话,尝试旧查询面')\r\n            } else {\r\n              console.warn('[dsh-prompt-optimizer] 当前会话没有可读的事件窗口,尝试旧查询面')\r\n            }\r\n          } catch (cause) {\r\n            console.warn('[dsh-prompt-optimizer] 读取会话事件窗口失败,尝试旧查询面:', cause)\r\n          }\r\n          try {\r\n            const history = legacyQueryFace(ctx.connection)?.sessions?.history\r\n            if (!history) {\r\n              console.warn('[dsh-prompt-optimizer] 会话历史查询面在当前 dsh 版本缺席,按无上下文优化')\r\n              return undefined\r\n            }\r\n            const result = await history({ sessionId, maxMessages: 24 }, controller.signal)\r\n            if (result.ok) {\r\n              const turns = extractContextTurns(result.value.events ?? [])\r\n              return turns.length ? turns : undefined\r\n            }\r\n            console.warn('[dsh-prompt-optimizer] 会话历史查询被拒绝,按无上下文优化:', result.error)\r\n          } catch (cause) {\r\n            console.warn('[dsh-prompt-optimizer] 会话历史查询失败,按无上下文优化:', cause)\r\n          }\r\n          return undefined\r\n        })(),\r\n      ])\r\n      const resp = await fetch(ROUTE, {\r\n        method: 'POST',\r\n        headers: { 'content-type': 'application/json' },\r\n        // sessionId 随请求带给 Host:Host 把它标注到 llm 调用上,要求会话头\r\n        // 的提供方(如 opencode 的 x-opencode-session)才能路由成功,同时\r\n        // 会话级计量会把这次调用归属到当前会话。\r\n        body: JSON.stringify({ text: draft, sessionId, provider: selection?.provider, model: selection?.model, reasoningEffort: selection?.reasoningEffort, context, previous }),\r\n        signal: controller.signal,\r\n      })\r\n      // 预校验失败(400/405/409/413/502)仍是普通 JSON;成功则进入 SSE 流。\r\n      if (!resp.ok || !(resp.headers.get('content-type') ?? '').includes('text/event-stream')) {\r\n        const data = await resp.json().catch(() => null)\r\n        if (!controller.signal.aborted) {\r\n          set({ status: 'error', live: null, error: String(data?.error ?? `请求失败(HTTP ${resp.status})`) })\r\n        }\r\n        return\r\n      }\r\n      const reader = resp.body?.getReader()\r\n      if (!reader) throw new Error('当前环境不支持流式响应')\r\n      const decoder = new TextDecoder()\r\n      let buffer = ''\r\n      let terminal = false\r\n      for (;;) {\r\n        const { done, value } = await reader.read()\r\n        if (done) break\r\n        buffer += decoder.decode(value, { stream: true })\r\n        let sep: number\r\n        while ((sep = buffer.indexOf('\\n\\n')) !== -1) {\r\n          const frame = buffer.slice(0, sep)\r\n          buffer = buffer.slice(sep + 2)\r\n          const line = frame.split('\\n').find((l) => l.startsWith('data:'))\r\n          if (!line) continue\r\n          // 单帧损坏(代理截断/编码异常)不得毁掉整次优化:跳过并告警,继续读流。\r\n          let event: Record<string, unknown>\r\n          try {\r\n            event = JSON.parse(line.slice(5).trim()) as Record<string, unknown>\r\n          } catch {\r\n            console.warn('[dsh-prompt-optimizer] 跳过无法解析的 SSE 帧:', line.slice(0, 120))\r\n            continue\r\n          }\r\n          if (event.type === 'delta') {\r\n            liveRaw += String(event.text ?? '')\r\n            if (!liveTimer) {\r\n              liveTimer = setTimeout(() => {\r\n                liveTimer = null\r\n                // 仅在仍是当前请求的 loading 期间落帧(竞态:retry/close 后旧定时器不得复活)。\r\n                if (state.status === 'loading' && abort === controller) {\r\n                  // R14:段落定格后压缩缓冲,压缩出的定格值在冻结字段里持有\r\n                  // (只在首次产出时采纳,避免后续帧把已冻结的段落清掉)。\r\n                  const comp = compactPartialBuffer(liveRaw)\r\n                  if (comp.compacted !== null) {\r\n                    if (comp.analysis) frozenAnalysis = comp.analysis\r\n                    if (comp.optimized) frozenOptimized = comp.optimized\r\n                    liveRaw = comp.compacted\r\n                  }\r\n                  const partial = parsePartialOptimizerOutput(liveRaw)\r\n                  const live = { analysis: partial.analysis || frozenAnalysis, optimized: partial.optimized || frozenOptimized }\r\n                  // 快速模式 + 模型不输出标记:解析不出任何段落时,原始流即优化稿本身,\r\n                  // 直接实时预览(整段空等到 done 比看到逐字增长糟得多)。缓冲里出现\r\n                  // 「<<<」视为标记正在形成,交回正常解析,避免把半个标记闪进预览。\r\n                  if (opts.isFastMode?.() && !live.analysis && !live.optimized && liveRaw.trim() && !liveRaw.includes('<<<')) {\r\n                    live.optimized = liveRaw.trim()\r\n                  }\r\n                  set({ live })\r\n                }\r\n              }, 50)\r\n            }\r\n          } else if (event.type === 'done') {\r\n            terminal = true\r\n            clearLiveTimer()\r\n            set({\r\n              status: 'done',\r\n              live: null,\r\n              result: {\r\n                analysis: String(event.analysis ?? ''),\r\n                optimized: String(event.optimized ?? ''),\r\n                wellFormed: event.wellFormed !== false,\r\n                truncated: event.truncated === true,\r\n                provider: String(event.provider ?? ''),\r\n                model: String(event.model ?? ''),\r\n                fallbackUsed: event.fallbackUsed === true,\r\n                fallbackReason: typeof event.fallbackReason === 'string' && event.fallbackReason ? event.fallbackReason : undefined,\r\n                durationMs: Date.now() - startedAt,\r\n              },\r\n            })\r\n          } else if (event.type === 'error') {\r\n            terminal = true\r\n            clearLiveTimer()\r\n            set({ status: 'error', live: null, error: String(event.error ?? '未知错误') })\r\n          }\r\n        }\r\n      }\r\n      if (!terminal) {\r\n        if (!controller.signal.aborted) {\r\n          clearLiveTimer()\r\n          set({ status: 'error', live: null, error: '连接中断:响应流提前结束' })\r\n        } else if (clientTimedOut && abort === controller) {\r\n          failTimeout()\r\n        }\r\n      }\r\n    } catch (cause) {\r\n      if (controller.signal.aborted) {\r\n        if (clientTimedOut && abort === controller) failTimeout()\r\n        return\r\n      }\r\n      set({ status: 'error', live: null, error: cause instanceof Error ? cause.message : String(cause) })\r\n    } finally {\r\n      clearTimeout(watchdog)\r\n    }\r\n  }\r\n\r\n  return {\r\n    subscribe(listener: () => void) {\r\n      listeners.add(listener)\r\n      return () => listeners.delete(listener)\r\n    },\r\n    getSnapshot: () => state,\r\n    optimize,\r\n    retry() {\r\n      // last.text 是**拆分后**的正文(斜杠命令前缀单独存在 last.prefix 里),\r\n      // 必须拼回前缀再重跑,否则 optimize 会丢掉命令词,「替换输入框」写回的\r\n      // 草稿也会缺前缀。\r\n      if (state.last) void optimize(joinLast(state.last), state.last.sessionId)\r\n    },\r\n    markApplied(applied: { backup: string; text: string }) {\r\n      set({ applied })\r\n    },\r\n    clearApplied() {\r\n      if (state.applied) set({ applied: null })\r\n    },\r\n    close() {\r\n      abort?.abort()\r\n      abort = null\r\n      clearLiveTimer()\r\n      set({ ...INITIAL })\r\n    },\r\n    /**\r\n     * O2:loading 中取消(Esc)。与 close 不同:中止请求但不清空状态,\r\n     * 面板定格展示已生成的部分——用户等了几十秒的内容不应一键蒸发。\r\n     * 后续可「重新优化」续跑或「关闭」彻底收起。\r\n     */\r\n    cancel() {\r\n      if (state.status !== 'loading') return\r\n      abort?.abort()\r\n      abort = null\r\n      clearLiveTimer()\r\n      set({ status: 'cancelled' })\r\n    },\r\n  }\r\n}\r\n\r\nexport type OptimizerController = ReturnType<typeof createOptimizerController>\r\n"
